import net.sf.jsqlparser.statement.select.Offset;
import net.sf.jsqlparser.statement.select.OrderByElement;
import net.sf.jsqlparser.schema.Column;
import net.sf.jsqlparser.expression.LongValue;
import net.sf.jsqlparser.expression.Expression;
import net.sf.jsqlparser.expression.Function;
import net.sf.jsqlparser.expression.operators.relational.GreaterThan;

public String convertToPageSql(String sql, Integer offset, Integer limit) {
    try {
        Statement stmt = CCJSqlParserUtil.parse(sql);

        if (!(stmt instanceof Select)) {
            throw new PageException("分页语句必须是Select查询!");
        }

        Select select = (Select) stmt;

        if (offset != null || limit != null) {
            PlainSelect plainSelect = (PlainSelect) select.getSelectBody();

            if (offset != null) {
                plainSelect.setTop(new Top(limit.toString()));
                plainSelect.setOffset(new Offset(offset.toString()));
            }

            Function rowNumberFunction = new Function();
            rowNumberFunction.setName("ROW_NUMBER");
            Column column = new Column("*");
            rowNumberFunction.setParameters(new ExpressionList(column));
            Function overFunction = new Function();
            overFunction.setName("OVER");
            rowNumberFunction.setKeep(overFunction);
            rowNumberFunction.setAlias("PAGE_ROW_NUMBER");

            plainSelect.getSelectItems().add(new SelectExpressionItem(rowNumberFunction));

            if (offset != null) {
                GreaterThan greaterThan = new GreaterThan();
                greaterThan.setLeftExpression(new Column("PAGE_ROW_NUMBER"));
                greaterThan.setRightExpression(new LongValue("1"));
                plainSelect.setWhere(greaterThan);
            }

            OrderByElement orderByElement = new OrderByElement();
            orderByElement.setExpression(new Column("PAGE_ROW_NUMBER"));
            plainSelect.getOrderByElements().add(orderByElement);

            String pageSql = plainSelect.toString();
            return pageSql;
        } else {
            return sql;
        }

    } catch (Throwable e) {
